import{_ as t,o,c as n,a2 as r}from"./chunks/framework.BXzK3EA4.js";const i="/assets/2a926f3b9230f71d.Ce9OObvV.png",s="/assets/df6d48eeb0d3af6c.D4pZem_i.png",a="/assets/80e1307b47163019.CfLtxY7h.png",p="/assets/e043258164dbc2a0.DezWpHxi.png",c="/assets/fef728b8a5070a72.DroX19QZ.png",S=JSON.parse('{"title":"CredSSP encryption oracle remediation error in Windows Remote Desktop","description":"","frontmatter":{"title":"CredSSP encryption oracle remediation error in Windows Remote Desktop"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/windows/credssp-encryption-oracle-remediation-error-in-windows-remote-desktop.md","filePath":"operations-knowledge-base/operating-system/windows/credssp-encryption-oracle-remediation-error-in-windows-remote-desktop.md","lastUpdated":1794292919000}'),l={name:"operations-knowledge-base/operating-system/windows/credssp-encryption-oracle-remediation-error-in-windows-remote-desktop.md"};function d(m,e,u,h,w,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<p><strong>Issue description: When attempting to connect to a Windows instance using Remote Desktop, &quot;An authentication error has occurred. The requested function is not supported.&quot;</strong> <strong>error message appears</strong></p><p><img src="'+i+'" alt=""></p><p>Root cause:</p><p>The issue is caused by a security update released by Microsoft in May 2018 that affects the Credential Security Support Provider protocol (CredSSP) and authentication request methods.</p><p>By default, after installing this update, patched local computers are unable to communicate with unpatched instances.</p><p>Solution:</p><p>Depending on the specific scenario, you can consider the following three solutions:</p><p>Solution 1 : Run the following command on the local PC</p><p>1.Open a CMD window with administrator privileges on the local PC. Run the following command:</p><p>reg add &quot;HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\CredSSP\\Parameters&quot; /v AllowEncryptionOracle /t REG_DWORD /d 2 /f</p><p>Solution 2: Allow Remote Desktop Connections on the instance</p><p>1.Use VNC to connect to the Windows system，Click on the Start menu and right-click on &quot;This PC&quot; (or &quot;My Computer&quot;) and select &quot;Properties&quot;.</p><p><img src="'+s+'" alt=""></p><ol start="3"><li>2.On the Control Panel main page, click on &quot;Remote Settings&quot;.</li></ol><p><img src="'+a+'" alt=""></p><ol start="4"><li>3.Under the &quot;Remote&quot; tab, uncheck the option &quot;Allow connections only from computers running Remote Desktop with Network Level Authentication (recommended)&quot;, and then click on &quot;OK&quot;.</li></ol><p><img src="'+p+'" alt=""></p><p>Solution Three: Modifying the Registry</p><p>1.Connect to the Windows system using VNC.</p><ol start="2"><li>Click on the &quot;Windows PowerShell&quot; in the lower-right corner to open it, and execute the following command to run the Windows PowerShell script as an administrator:</li></ol><p><img src="'+c+'" alt=""></p><ul><li><p>New-Item -Path HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System -Name CredSSP -Force</p></li><li><p>New-Item -Path HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\CredSSP -Name Parameters -Force</p></li><li><p>Get-Item -Path HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\CredSSP\\Parameters | New-ItemProperty -Name AllowEncryptionOracle -Value 2 -PropertyType DWORD -Force</p></li></ul><p>3.The changes will take effect after rebooting the machine.</p>',23)])])}const _=t(l,[["render",d]]);export{S as __pageData,_ as default};
